package Java_basic_pgm;

public class chowkoncha_programme_karane {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int i=5;i>=0;i--)
		{
			for(int j=0;j<=i;j++)
			{
				System.out.print(" ");
			}
			
			for(int k=i;k<=5;k++) 
			{
				System.out.print(" x");

			}
			System.out.println();

			
					}
		
			
	}
}
		
		
